import{j as e}from"./motion-framer-CfsFicUq.js";import{S as t}from"./ServicePageLayout-mswu4ys3.js";import{a as o}from"./index-Cp_-rLRh.js";import"./motion-gsap-a3sj5zmn.js";import"./button-U6YGi0FM.js";import"./PageBanner-DI0ZdnbO.js";import"./Breadcrumbs-C5_K0Tm4.js";import"./chevron-right-54xlIn0d.js";function p(){return e.jsx(t,{title:"SMS Surveys",subtitle:"Customer Feedback That Reaches Every Phone in Kenya",description:"Collect customer and market feedback with two-way SMS surveys that work on any phone — no app, no data. MobiWave gives you branching questions, real-time tracking, analytics and automatic reminders, with CAK-aligned sender IDs registered for you across Safaricom, Airtel and Telkom.",icon:o,stats:[{value:"Two-way",label:"SMS"},{value:"Real-time",label:"Analytics"},{value:"All phones",label:"No App Needed"},{value:"Swahili",label:"Supported"}],features:["Two-way SMS survey flows","Branching and skip-logic questions","Real-time response tracking","Analytics dashboard with export","Automated reminder nudges","CAK-aligned sender ID included","Opt-in / opt-out compliance ledger","Webhook delivery of responses","NPS and rating question types","Bundled with bulk SMS and WhatsApp"],benefits:["Reach everyone — feature phones included, no data","Higher response rates than email surveys","Instant results with live dashboards","Compliance-ready opt-in and opt-out tracking","Multilingual surveys in Swahili and English","24/7 local Nairobi support via phone and WhatsApp"],useCases:[{title:"Customer satisfaction (CSAT)",description:"Measure post-purchase or post-support satisfaction with quick rating questions."},{title:"Net Promoter Score (NPS)",description:"Run NPS campaigns and segment promoters from detractors for follow-up."},{title:"Market research",description:"Gather opinions and preferences across regions where smartphone penetration is low."},{title:"Event feedback",description:"Collect attendee feedback immediately after a service or event via two-way SMS."},{title:"Employee engagement",description:"Pulse-check field and branch staff anonymously over a familiar channel."},{title:"Product & pricing polls",description:"Test demand and price sensitivity with keyword-based poll questions."},{title:"Public-sector consultation",description:"Run citizen feedback and service-quality surveys for government and NGOs."},{title:"Health & ag advisory",description:"Check adherence and gather farmer or patient feedback on advisories sent by SMS."}],howItWorks:[{step:"1",title:"Register your sender ID",description:"MobiWave registers your CAK-aligned sender ID on Safaricom, Airtel and Telkom during onboarding at no extra admin fee, so surveys arrive from a trusted, recognized name."},{step:"2",title:"Design the survey",description:"Build questions in the dashboard or API — single choice, rating, NPS or open text — with branching so later questions depend on earlier answers."},{step:"3",title:"Send and collect",description:"Dispatch to a segmented list over two-way SMS. Responses stream back in real time and post to your webhook for your own systems."},{step:"4",title:"Remind non-responders",description:"Automated nudges re-message people who haven’t replied, lifting completion without manual chasing."},{step:"5",title:"Analyze",description:"Track completion, distributions and drop-off in the analytics dashboard, and export CSV or wire results into your BI tools."},{step:"6",title:"Act and bundle",description:"Trigger follow-ups from results and combine surveys with bulk SMS, USSD and WhatsApp on one MobiWave account."}],comparisonTable:{headers:["MobiWave","Africa's Talking","Celcom Africa","Twilio"],note:"All providers support two-way SMS surveys. MobiWave bundles surveys with SMS, USSD and WhatsApp and handles CAK sender-ID registration at no admin fee.",rows:[{name:"Two-way SMS surveys",cells:[{text:"Included",highlight:!0},{text:"Add-on"},{text:"Add-on"},{text:"Add-on"}]},{name:"Branching / skip logic",cells:[{text:"Yes",highlight:!0},{text:"DIY via API"},{text:"DIY"},{text:"DIY"}]},{name:"Sender ID registration",cells:[{text:"Free, handled for you",highlight:!0},{text:"KES 7,000 / network"},{text:"KES 7,000 / network"},{text:"Via aggregator"}]},{name:"Real-time analytics",cells:[{text:"Dashboard + webhook",highlight:!0},{text:"API only"},{text:"API only"},{text:"API only"}]},{name:"Reminder automation",cells:[{text:"Built-in",highlight:!0},{text:"DIY"},{text:"DIY"},{text:"DIY"}]},{name:"Local 24/7 support",cells:[{text:"Phone + WhatsApp",highlight:!0},{text:"Developer-only"},{text:"Business hours"},{text:"No local team"}]}]},pricing:[{title:"Pay-per-SMS",price:"Usage-based",unit:"",features:["Two-way survey flows","Branching questions","Real-time dashboard","Per-SMS rate applies","Standard support"]},{title:"Research",price:"Usage-based",unit:"",features:["Everything in Pay-per-SMS","Reminder automation","NPS & rating types","CSV / webhook export","24/7 support"]},{title:"Enterprise",price:"Custom",unit:"",features:["High-volume campaigns","Custom SLAs","BI integrations","Dedicated account manager"]}],faqs:[{question:"How much does an SMS survey cost in Kenya?",answer:"You pay per SMS sent and received at MobiWave’s standard bulk SMS rate (from KES 0.20–0.35 depending on volume), plus no extra fee for the survey tooling itself. There are no setup fees. Contact us for volume pricing."},{question:"What response rates can I expect?",answer:"SMS surveys typically outperform email, especially among customers without smartphones or reliable data. Response lifts further with a recognized sender ID, short questions and one automated reminder — which MobiWave supports out of the box."},{question:"Can I ask different questions based on answers?",answer:"Yes. MobiWave supports branching and skip logic, so a “No” can route to a different follow-up than a “Yes”, keeping surveys short and relevant."},{question:"Does it work on feature phones?",answer:"Yes. SMS surveys run on every GSM phone with no app or internet, making them ideal for reaching rural and low-connectivity audiences across Kenya."},{question:"Can surveys be in Swahili?",answer:"Yes. Questions, responses and reminders can be written in Swahili or English, and you can localize per audience segment."},{question:"How do you keep surveys compliant?",answer:"We maintain an opt-in / opt-out ledger and honor STOP-to-unsubscribe on every flow, supporting ODPC data-protection and CAK advertising rules. Survey data is handled under MobiWave’s privacy commitments."},{question:"Can I run NPS over SMS?",answer:"Yes. NPS and rating question types are supported, with results segmented into promoters, passives and detractors for follow-up."},{question:"Where do responses go?",answer:"Responses appear in the real-time dashboard and are also posted to your webhook, so you can pipe them into your CRM, data warehouse or BI tool."},{question:"Can I send surveys over WhatsApp too?",answer:"Yes. The same survey logic can run over WhatsApp for customers who prefer it, on the same MobiWave account and billing line."},{question:"How is MobiWave different from Africa’s Talking?",answer:"Both support two-way SMS. MobiWave includes branching surveys, reminder automation and a real-time dashboard as part of the service, registers your CAK sender ID for free, and bundles SMS with USSD and WhatsApp — with 24/7 local support rather than developer-only."}]})}export{p as SMSSurveys};
